validator:
function validate(input) {
  const [{ Tweets = [] }] = input;
  const ids = new Set();
  for (const [id, content] of Tweets) {
    if (id === null) return 'Every tweet needs a tweet_id.';
    if (ids.has(id)) return `tweet_id ${id} appears twice.`;
    ids.add(id);
    if (typeof content !== 'string') return `Tweet ${id} needs its content.`;
    if (content.length > 500) return `Tweet ${id} is longer than 500 characters.`;
    if (!/^[\x20-\x7E]*$/.test(content)) return `Tweet ${id} may only use printable ASCII characters.`;
    if (/[^ ][@#]/.test(content)) return `In tweet ${id}, @ and # must start a word.`;
    if (/[@#](?![A-Za-z0-9])/.test(content)) return `In tweet ${id}, @ and # must be followed by a letter or digit.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const openers = ['What an amazing meal', 'Learning something new every day', "So grateful for today's experiences", 'What a beautiful day it is', 'Work hard, play hard, and cherish every moment', 'Traveling, exploring, and living my best life'];
  const users = ['@MaxPower', '@AlexJones', '@JohnDoe', '@AnnaWilson', '@SaraJohnson', '@JaneSmith', '@ChrisAnderson', '@LisaTaylor', '@MikeBrown', '@EmilyClark'];
  const tags = ['#Learning', '#Fitness', '#Love', '#Foodie', '#Fashion', '#WorkLife', '#Travel', '#HappyDay', '#Nature', '#Art', '#TechLife', '#Music'];
  // Counts cluster around the limit of 3 so both sides of every rule show up.
  const howMany = () => pick([0, 1, 2, 3, 3, 3, 4, 4, 5]);
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Tweets = [];
  let id = 0;
  for (let i = 0; i < count; i++) {
    id += 1 + Math.floor(rand() * 3);
    const words = [pick(openers)];
    const mentions = Array.from({ length: howMany() }, () => pick(users));
    const hashtags = Array.from({ length: howMany() }, () => pick(tags));
    let content = [...words, ...mentions, ...hashtags].join(' ');
    // Sometimes stretch the text to a length right around the 140-character limit.
    if (rand() < 0.4) {
      const target = 136 + Math.floor(rand() * 9);
      const gap = target - content.length;
      if (gap >= 3) content = [words[0], `S${'o'.repeat(gap - 2)}`, ...mentions, ...hashtags].join(' ');
    }
    Tweets.push([id, content]);
  }
  // Shuffle so the rows do not arrive in tweet_id order.
  for (let i = Tweets.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Tweets[i], Tweets[j]] = [Tweets[j], Tweets[i]];
  }
  return [{ Tweets }];
}
